mapper.select:
SELECT w.wish_id, p.property_id, p.district, p.deposit, ra.risk_grade, ra.previous_grade, w.created_at AT TIME ZONE 'Asia/Seoul' AS added_at FROM wishlist w JOIN property p ON p.property_id = w.property_id LEFT JOIN risk_analysis ra ON ra.property_id = w.property_id AND ra.is_latest WHERE w.user_id = #{userId}
AND w.wish_id < #{lastWishId}
ORDER BY w.wish_id DESC LIMIT #{limit}

SELECT DISTINCT w.property_id
FROM wishlist w


        w.property_id > #{lastPropertyId}


ORDER BY w.property_id
LIMIT #{limit}
